<script lang="ts">
 import NavIcon from './NavIcon.svelte';
 import type {Snippet} from 'svelte';
 import {onMount} from 'svelte';
 import {page} from '$app/state';
 import '$lib/components/ui/tokens.css';
 import SceneBanner, {type Banner} from './SceneBanner.svelte';
 let {children,tools=false,siteName='个人综合站',intro='记录想法、分享作品，收藏日常。',banner=null}:{children:Snippet;tools?:boolean;siteName?:string;intro?:string;banner?:Banner|null}=$props();
 let theme=$state('system');let menuOpen=$state(false);let scrollY=$state(0);let settingsOpen=$state(false);let backdrop=$state(true);let reducedMotion=$state(false);
 const home=$derived(page.url.pathname==='/');
 const showScene=$derived(home && backdrop);
 function setBackdrop(value:boolean){backdrop=value;document.documentElement.dataset.sceneBackground=String(value);try{localStorage.setItem('scene-background',String(value));}catch{/* optional */}}
 const links=[['/articles','文章','articles'],['/notes','笔记','notes'],['/moments','动态','moments'],['/projects','作品','projects']];
 const extraLinks=[['/resources','资源','resources'],['/tags','标签','tags'],['/series','系列','series'],['/about','关于','about']];
 let moreOpen=$state(false);
 let closeTimer:ReturnType<typeof setTimeout>|undefined;
 function cancelClose(){clearTimeout(closeTimer);closeTimer=undefined;}
 function closeSettings(){cancelClose();settingsOpen=false;}
 function pointerMoved(event:PointerEvent){
  if(!settingsOpen||event.pointerType==='touch')return;
  const inside=(event.target as Element)?.closest('#display-settings,.settings-trigger,.utility-settings');
  if(inside){cancelClose();return;}
  if(!closeTimer)closeTimer=setTimeout(closeSettings,220);
 }

 const section=$derived([...links,...extraLinks,['/tools','工具','tools']].find(([href])=>isActive(href)));
 $effect(()=>{void page.url.pathname;moreOpen=false;settingsOpen=false;menuOpen=false;});
 const activePath=$derived(page.url.pathname);
 const isActive=(href:string)=>activePath===href||activePath.startsWith(`${href}/`);
 function setTheme(value:string){theme=value;document.documentElement.dataset.theme=value;try{localStorage.setItem('theme',value);}catch{/* optional */}}
 function setMotion(value:boolean){reducedMotion=value;document.documentElement.dataset.motion=value?'reduced':'full';try{localStorage.setItem('motion',value?'reduced':'full');}catch{/* optional */}}
 onMount(()=>{try{const value=localStorage.getItem('theme');if(value&&['light','dark','system'].includes(value))setTheme(value);const savedBackdrop=localStorage.getItem('scene-background');if(savedBackdrop!==null)backdrop=savedBackdrop!=='false';document.documentElement.dataset.sceneBackground=String(backdrop);const motion=localStorage.getItem('motion');if(motion==='reduced')setMotion(true);}catch{/* optional */}return cancelClose;});
</script>
<svelte:window bind:scrollY onpointermove={pointerMoved} onkeydown={e=>{if(e.key==='Escape'){closeSettings();moreOpen=false;}}} onpointerdown={e=>{if(settingsOpen&&!(e.target as Element)?.closest('#display-settings,.settings-trigger,.utility-settings'))closeSettings();}} />
<svelte:head><meta name="color-scheme" content="light dark" /></svelte:head>
<a class="skip" href="#public-main">跳到主要内容</a>
<header class="site-header" class:home-header={showScene} class:over-scene={showScene && scrollY<320 && !menuOpen}>
 <div class="nav-inner">
  <a class="brand-profile" href="/" aria-label={`${siteName}首页`}><img src="/images/makeine-anna.png" alt="八奈见杏菜头像" width="34" height="34" /><span class="brand-profile-copy"><strong>{siteName}</strong><small>记录、创作与小小日常</small></span></a>
  <nav class="desktop-nav" aria-label="主要导航">{#each links as [href,label,icon]}<a {href} class:active={isActive(href)} aria-current={isActive(href)?'page':undefined}><NavIcon name={icon}/>{label}</a>{/each}{#if tools}<a href="/tools" class:active={isActive('/tools')}><NavIcon name="tools"/>工具</a>{/if}<a href="/search" class:active={isActive('/search')}><NavIcon name="search"/>搜索</a>
  <details class="more-nav" open={moreOpen} onmouseenter={()=>moreOpen=true} onmouseleave={()=>moreOpen=false} ontoggle={e=>moreOpen=e.currentTarget.open}><summary class="more-trigger"><NavIcon name="more"/>更多</summary><div id="more-links" class="menu">{#each extraLinks as [href,label,icon]}<a {href}><NavIcon name={icon}/>{label}</a>{/each}</div></details></nav>
  <div class="header-actions"><button class="settings-trigger" type="button" aria-expanded={settingsOpen} aria-controls="display-settings" onclick={()=>settingsOpen=!settingsOpen}><NavIcon name="settings"/><span>显示设置</span></button><button class="menu-toggle" type="button" aria-expanded={menuOpen} aria-controls="mobile-menu" onclick={()=>menuOpen=!menuOpen}>{menuOpen?'关闭':'菜单'}</button></div>
 </div>
 {#if settingsOpen}<div id="display-settings" class="settings-popover"><div><strong>显示设置</strong><button class="close-settings" type="button" onclick={()=>settingsOpen=false} aria-label="关闭显示设置">×</button></div><p class="setting-heading">外观主题</p><div class="theme-switcher" role="group" aria-label="主题">{#each [['system','跟随系统','system'],['light','浅色','sun'],['dark','深色','moon']] as [value,label,icon]}<button type="button" class:active={theme===value} aria-pressed={theme===value} onclick={()=>setTheme(value)}><NavIcon name={icon}/><span>{label}</span></button>{/each}</div><label class="setting-row"><span>首页场景与背景纹理</span><input type="checkbox" checked={backdrop} onchange={e=>setBackdrop(e.currentTarget.checked)} /></label><label class="setting-row"><span>减少动效</span><input type="checkbox" checked={reducedMotion} onchange={e=>setMotion(e.currentTarget.checked)} /></label><small>{backdrop?'背景已开启':'背景已关闭：纯色阅读模式'}。{reducedMotion?'动效已暂停。':'动效跟随系统偏好。'}选择会保存在此浏览器。</small></div>{/if}
 {#if menuOpen}<nav id="mobile-menu" class="mobile-menu" aria-label="移动端导航">{#each [...links,...(tools?[['/tools','工具','tools']]:[]),['/search','搜索','search'],...extraLinks] as [href,label,icon]}<a {href} class:active={isActive(href)} onclick={()=>menuOpen=false}><NavIcon name={icon}/>{label}</a>{/each}</nav>{/if}
</header>
{#if showScene}<SceneBanner {siteName} {banner} />{/if}
<div class="public-shell" class:home-shell={showScene} class:plain-background={!backdrop} id="public-main">
 <aside class="space-sidebar" aria-label="个人空间">
  <a class="profile-art" href="/about"><img src="/images/makeine-img_visual03.jpg" alt="八奈见杏菜" width="260" height="220" /></a>
  <div class="profile-copy"><div class="profile-kicker">PERSONAL SPACE</div><h2>{siteName}</h2><p>{intro}</p><div class="profile-links"><a href="/about">关于这里 ↗</a><a href="/rss.xml">RSS ↗</a></div></div>
  <nav class="section-nav" aria-label="空间栏目"><h3>在这里逛逛</h3>{#each [...links,['/tools','工具','tools'],['/resources','资源','resources'],['/tags','标签','tags'],['/series','系列','series']] as [href,label,icon]}<a {href} class:active={isActive(href)}><span><NavIcon name={icon}/> {label}</span><span aria-hidden="true">↗</span></a>{/each}</nav>
 </aside>
 <div class="content-column">{@render children()}</div>
 <aside class="utility-sidebar" aria-label="站点工具">
  <section class="utility-block"><p class="utility-kicker">STATS</p><a href="/articles"><span>文章</span><b>记录</b></a><a href="/moments"><span>动态</span><b>日常</b></a><a href="/projects"><span>作品</span><b>创作</b></a><a href="/tags"><span>标签</span><b>探索</b></a></section>
  <section class="utility-block"><p class="utility-kicker">NOW BROWSING</p><strong>{home?'首页':section?.[1]??'站点栏目'}</strong><p class="utility-copy">慢慢浏览，随手记下值得回看的东西。</p></section><section class="utility-block"><p class="utility-kicker">QUICK LINKS</p><a href="/updates">最近更新 <span>↗</span></a><a href="/search">站内搜索 <span>⌕</span></a><a href="/rss.xml">订阅 RSS <span>↗</span></a></section>
  <section class="utility-block utility-status"><p class="utility-kicker">SITE STATUS</p><div><span class="status-dot"></span><span>在线记录中</span></div><small>最后更新 · {new Date().toLocaleDateString('zh-CN')}</small></section>
  <button class="utility-settings" type="button" onclick={()=>settingsOpen=!settingsOpen}>☼ 显示设置</button>
 </aside>
</div>
<footer><div class="footer-inner"><p class="footer-signature">把好奇心写成记录，把过程留给以后。</p><nav aria-label="页脚导航"><a href="/articles">文章</a><a href="/notes">笔记</a><a href="/projects">作品</a><a href="/about">关于</a><a href="/rss.xml">RSS</a></nav><p class="muted">© {new Date().getFullYear()} {siteName}</p></div></footer>
<style>
:global(body:has(.public-shell)){background-color:var(--canvas);background-image:radial-gradient(color-mix(in srgb,var(--primary) 8%,transparent) 1px,transparent 1px);background-size:18px 18px}
:global(body:has(.public-shell.plain-background)){background-image:none}:global(html[data-scene-background='false'] body){background-image:none!important}
.site-header{position:sticky;top:0;z-index:20;background:var(--surface);border-bottom:1px solid var(--line)}.site-header.home-header{position:fixed;inset:0 0 auto;background:transparent;border-bottom-color:transparent;box-shadow:none}.site-header.home-header:not(.over-scene){background:var(--surface);border-bottom-color:var(--line);box-shadow:0 6px 24px #1d24420d}.site-header.over-scene{background:transparent;border-bottom-color:transparent;color:white;box-shadow:none}.nav-inner{max-width:1400px;min-height:64px;margin:auto;padding:7px 22px;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:16px}.brand-profile{display:flex;align-items:center;gap:10px;text-decoration:none;color:inherit;min-width:0}.brand-profile img{width:34px;height:34px;border-radius:50%;flex-shrink:0}.brand-profile-copy{display:grid;line-height:1.3;gap:2px}.brand-profile-copy strong{font-size:14px}.brand-profile-copy small{font-size:10px;color:var(--muted)}.over-scene .brand-profile-copy small{color:#e8eff6}.desktop-nav{display:flex;align-items:center;gap:2px}.desktop-nav a,.desktop-nav .more-trigger{display:inline-flex;gap:5px;align-items:center;min-height:40px;padding:6px 11px;border-radius:4px;color:inherit;text-decoration:none;font-size:13px}.desktop-nav a:hover,.desktop-nav .more-trigger:hover,.desktop-nav a.active{background:transparent;color:var(--primary);text-shadow:none;border-bottom:2px solid currentColor}.over-scene .desktop-nav a:hover,.over-scene .desktop-nav a.active{background:transparent;color:#fff;border-bottom-color:#fff}.more-nav{position:relative}.more-trigger{border:0;background:transparent;color:inherit;font-weight:inherit;cursor:pointer;list-style:none}.more-trigger::-webkit-details-marker{display:none}.menu{position:absolute;right:0;top:100%;z-index:30;display:grid;min-width:132px;padding:7px;background:var(--surface);color:var(--text);text-shadow:none;border:1px solid var(--line);border-radius:11px;box-shadow:var(--shadow-sm)}.menu a{color:var(--text)!important}.header-actions{justify-self:end;display:flex;align-items:center;gap:7px}.setting-heading{font-size:12px;color:var(--muted);margin:6px 0}.theme-switcher{margin-bottom:16px;display:flex;align-items:center;gap:2px;padding:2px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--surface) 65%,transparent)}.theme-switcher button{display:inline-flex;align-items:center;gap:4px;flex:1;flex-direction:column;min-height:62px;padding:8px;border:0;border-radius:7px;background:transparent;color:var(--muted);font-size:11px}.theme-switcher button.active,.theme-switcher button:hover{background:var(--soft);color:var(--text)}.over-scene .menu-toggle{background:transparent;color:#fff;border-color:#ffffff55}.settings-trigger,.utility-settings{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:5px 10px;border:0;border-radius:0;background:transparent;font-size:12px}.over-scene .settings-trigger{color:#fff}.settings-trigger:hover{color:var(--primary);background:transparent}.over-scene .settings-trigger:hover{color:#fff;opacity:.8}.settings-popover{position:absolute;right:22px;top:66px;width:min(320px,calc(100vw - 32px));padding:18px;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:13px;box-shadow:0 18px 48px #14223926}.settings-popover>div{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.settings-popover strong{font-size:13px}.close-settings{border:0;background:none;min-height:28px;padding:2px 6px}.setting-row{display:flex;align-items:center;justify-content:space-between;min-height:38px;margin:0;border-top:1px solid var(--line);font-size:12px}.setting-row input{width:18px;min-height:18px}.settings-popover small{display:block;font-size:10px;line-height:1.6;margin-top:8px}.menu-toggle{display:none}.mobile-menu{display:none}
.public-shell{max-width:1440px;margin:auto;padding:28px 22px 56px;display:grid;grid-template-columns:258px minmax(0,1fr) 246px;gap:18px;align-items:start;min-height:75vh}.home-shell{position:relative;margin-top:0;padding-top:20px;z-index:4}.space-sidebar,.utility-sidebar{background:transparent;border:0;border-radius:0;overflow:hidden;position:sticky;top:92px;min-width:0}.profile-art{display:block;margin:0;overflow:hidden;border-radius:18px 18px 4px 4px}.profile-art img{display:block;width:100%;height:205px;object-fit:cover;object-position:center 22%}.profile-copy{padding:20px 14px 16px;border-bottom:1px solid var(--line)}.profile-kicker,.utility-kicker{font:10px/1.4 'DM Mono',monospace;letter-spacing:.12em;color:var(--primary);margin:0 0 6px}.profile-copy h2{font-size:19px;margin:0 0 7px}.profile-copy p{font-size:12px;color:var(--muted);line-height:1.75;margin-bottom:9px}.profile-links{display:flex;gap:14px}.profile-links a{display:inline-flex;align-items:center;min-height:34px;font-size:12px;text-decoration:none}.section-nav{padding:8px 13px 15px;border-top:1px solid var(--line)}.section-nav h3{font-size:11px;color:var(--muted);margin:10px 8px 5px}.section-nav>a{display:flex;justify-content:space-between;align-items:center;min-height:36px;padding:5px 9px;text-decoration:none;color:var(--text);border-radius:7px;font-size:13px}.section-nav>a.active,.section-nav>a:hover{background:var(--soft);color:var(--primary)}.content-column{min-width:0}.utility-sidebar{padding:8px 0 8px 20px;border-left:1px solid var(--line)}.utility-block{padding:5px 0 16px;margin-bottom:14px;border-bottom:1px solid var(--line)}.utility-block:last-of-type{margin-bottom:0}.utility-block strong{display:block;font-size:17px;margin:3px 0 6px}.utility-copy{font-size:12px;color:var(--muted);line-height:1.7;margin:0}.utility-block>a{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:34px;padding:3px 0;color:var(--text);font-size:12px;text-decoration:none;border-bottom:1px dotted var(--border)}.utility-block>a b{font-weight:500;color:var(--muted)}.utility-block>a:hover{color:var(--primary)}.utility-block>a span{color:var(--muted)}.utility-status>div{display:flex;align-items:center;gap:7px;font-size:12px}.status-dot{width:7px;height:7px;border-radius:50%;background:#76b58a;box-shadow:0 0 0 3px #76b58a1f}.utility-status small{display:block;color:var(--muted);font-size:10px;margin-top:7px}.utility-settings{width:100%;margin-top:2px;color:var(--muted)}.utility-settings:hover{color:var(--primary);border-color:var(--primary)}footer{border-top:1px solid var(--line)}.footer-inner{max-width:1440px;margin:auto;padding:24px;display:flex;justify-content:space-between;gap:24px;align-items:center;font-size:12px;color:var(--muted)}.footer-inner p{margin:0}.footer-inner nav{display:flex;flex-wrap:wrap;gap:16px}.footer-inner a{text-decoration:none;color:inherit}.skip{position:fixed;left:16px;top:12px;transform:translateY(-200%);padding:12px 16px;background:var(--surface);border-radius:9px;z-index:40}.skip:focus{transform:none}:global(.public-shell){overflow-wrap:anywhere;scroll-margin-top:84px}:global(.public-shell :focus-visible){scroll-margin-block:84px}
@media(max-width:1180px){.public-shell{grid-template-columns:224px minmax(0,1fr) 210px;gap:14px;padding-inline:16px}.nav-inner{gap:12px}.desktop-nav a,.desktop-nav .more-trigger{padding-inline:8px}.brand-profile-copy small{display:none}}
@media(max-width:1060px){.brand-profile-copy small{display:none}.nav-inner{gap:8px}.desktop-nav a,.desktop-nav .more-trigger{padding-inline:6px}}
@media(max-width:950px){.utility-sidebar{display:none}.public-shell{grid-template-columns:210px minmax(0,1fr)}.settings-trigger span{display:none}}
@media(max-width:760px){.site-header,.site-header.home-header{top:8px;inset-inline:8px;margin:0;border-radius:13px}.desktop-nav{display:none}.menu-toggle{display:block}.mobile-menu{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:9px 12px;gap:5px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 13px 13px}.mobile-menu a{display:flex;align-items:center;gap:8px;padding:8px;text-decoration:none;color:var(--text);min-height:40px;font-size:13px}.mobile-menu a.active{background:var(--soft)}.nav-inner{padding-inline:10px;grid-template-columns:1fr auto}.public-shell{display:block;padding:18px 13px 36px}.home-shell{padding-top:16px;margin-top:0}.space-sidebar{display:none}.brand-profile-copy strong{font-size:13px}.settings-popover{right:10px;top:58px}.footer-inner{flex-wrap:wrap;padding:22px 16px;gap:12px}.footer-signature{width:100%}}
</style>
